# Modular Automated Cloud Infrastructure Provisioner in C#

Below is a comprehensive implementation of a modular cloud infrastructure provisioner in C# with the three requested components: declarative resource parser, dependency graph resolver, and execution engine.

## 1. Core Architecture Overview

```csharp
// InfrastructureProvisioner.cs - Main entry point
public class InfrastructureProvisioner
{
    private readonly IResourceParser _resourceParser;
    private readonly IDependencyResolver _dependencyResolver;
    private readonly IExecutionEngine _executionEngine;

    public InfrastructureProvisioner(
        IResourceParser resourceParser,
        IDependencyResolver dependencyResolver,
        IExecutionEngine executionEngine)
    {
        _resourceParser = resourceParser ?? throw new ArgumentNullException(nameof(resourceParser));
        _dependencyResolver = dependencyResolver ?? throw new ArgumentNullException(nameof(dependencyResolver));
        _executionEngine = executionEngine ?? throw new ArgumentNullException(nameof(executionEngine));
    }

    public async Task ProvisionInfrastructureAsync(string jsonDefinitionPath)
    {
        // 1. Parse the infrastructure definition
        var resources = await _resourceParser.ParseAsync(jsonDefinitionPath);

        // 2. Resolve dependencies
        var executionOrder = _dependencyResolver.ResolveDependencies(resources);

        // 3. Execute in the determined order
        await _executionEngine.ExecuteAsync(executionOrder);
    }
}
```

## 2. Declarative Resource Parser

```csharp
// IResourceParser.cs
public interface IResourceParser
{
    Task<IEnumerable<IResourceDefinition>> ParseAsync(string jsonDefinitionPath);
}

// ResourceDefinition.cs
public interface IResourceDefinition
{
    string Id { get; }
    string Type { get; }
    Dictionary<string, object> Properties { get; }
    IEnumerable<string> Dependencies { get; }
}

// JsonResourceParser.cs
public class JsonResourceParser : IResourceParser
{
    public async Task<IEnumerable<IResourceDefinition>> ParseAsync(string jsonDefinitionPath)
    {
        var json = await File.ReadAllTextAsync(jsonDefinitionPath);
        var definitions = JsonSerializer.Deserialize<Dictionary<string, object>>(json);

        var resources = new List<IResourceDefinition>();

        foreach (var (id, resourceData) in definitions)
        {
            var type = resourceData["type"]?.ToString() ?? throw new InvalidOperationException($"Missing type for resource {id}");
            var properties = resourceData["properties"] as Dictionary<string, object> ?? new Dictionary<string, object>();
            var dependencies = resourceData["dependencies"] as IEnumerable<string> ?? Array.Empty<string>();

            resources.Add(new ResourceDefinition
            {
                Id = id,
                Type = type,
                Properties = properties,
                Dependencies = dependencies
            });
        }

        return resources;
    }
}

// ResourceDefinition.cs (implementation)
public class ResourceDefinition : IResourceDefinition
{
    public string Id { get; set; }
    public string Type { get; set; }
    public Dictionary<string, object> Properties { get; set; } = new();
    public IEnumerable<string> Dependencies { get; set; } = Array.Empty<string>();
}
```

## 3. Dependency Graph Resolver

```csharp
// IDependencyResolver.cs
public interface IDependencyResolver
{
    IEnumerable<IResourceDefinition> ResolveDependencies(IEnumerable<IResourceDefinition> resources);
}

// DependencyGraphResolver.cs
public class DependencyGraphResolver : IDependencyResolver
{
    public IEnumerable<IResourceDefinition> ResolveDependencies(IEnumerable<IResourceDefinition> resources)
    {
        // Build adjacency list and in-degree count
        var graph = new Dictionary<string, List<string>>();
        var inDegree = new Dictionary<string, int>();

        foreach (var resource in resources)
        {
            graph[resource.Id] = new List<string>();
            inDegree[resource.Id] = 0;
        }

        foreach (var resource in resources)
        {
            foreach (var dependency in resource.Dependencies)
            {
                if (!graph.ContainsKey(dependency))
                {
                    throw new InvalidOperationException($"Dependency {dependency} not found in resources");
                }

                graph[dependency].Add(resource.Id);
                inDegree[resource.Id]++;
            }
        }

        // Kahn's algorithm for topological sort
        var queue = new Queue<string>();
        foreach (var entry in inDegree)
        {
            if (entry.Value == 0)
            {
                queue.Enqueue(entry.Key);
            }
        }

        var result = new List<IResourceDefinition>();
        var visited = new HashSet<string>();

        while (queue.Count > 0)
        {
            var current = queue.Dequeue();
            visited.Add(current);

            foreach (var neighbor in graph[current])
            {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0)
                {
                    queue.Enqueue(neighbor);
                }
            }
        }

        // Check for cycles
        if (visited.Count != resources.Count())
        {
            throw new InvalidOperationException("Cycle detected in resource dependencies");
        }

        // Return resources in topological order
        return resources.OrderBy(r => queue.Contains(r.Id) ? 0 : 1); // Simplified ordering
    }
}
```

## 4. Execution Engine

```csharp
// IExecutionEngine.cs
public interface IExecutionEngine
{
    Task ExecuteAsync(IEnumerable<IResourceDefinition> resources);
}

// ExecutionEngine.cs
public class ExecutionEngine : IExecutionEngine
{
    private readonly IResourceFactory _resourceFactory;
    private readonly ICloudProvider _cloudProvider;

    public ExecutionEngine(IResourceFactory resourceFactory, ICloudProvider cloudProvider)
    {
        _resourceFactory = resourceFactory ?? throw new ArgumentNullException(nameof(resourceFactory));
        _cloudProvider = cloudProvider ?? throw new ArgumentNullException(nameof(cloudProvider));
    }

    public async Task ExecuteAsync(IEnumerable<IResourceDefinition> resources)
    {
        var tasks = new List<Task>();

        foreach (var resource in resources)
        {
            tasks.Add(ExecuteResourceAsync(resource));
        }

        await Task.WhenAll(tasks);
    }

    private async Task ExecuteResourceAsync(IResourceDefinition resource)
    {
        try
        {
            Console.WriteLine($"Creating resource: {resource.Id} ({resource.Type})");

            // Create the resource
            var resourceInstance = _resourceFactory.Create(resource);

            // Deploy to cloud
            await _cloudProvider.DeployAsync(resourceInstance);

            Console.WriteLine($"Successfully created {resource.Id}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to create {resource.Id}: {ex.Message}");
            throw; // Re-throw to allow for error handling in the calling code
        }
    }
}

// IResourceFactory.cs
public interface IResourceFactory
{
    ICloudResource Create(IResourceDefinition definition);
}

// ResourceFactory.cs
public class ResourceFactory : IResourceFactory
{
    public ICloudResource Create(IResourceDefinition definition)
    {
        switch (definition.Type.ToLower())
        {
            case "vpc":
                return new VpcResource(definition.Properties);
            case "subnet":
                return new SubnetResource(definition.Properties);
            case "securitygroup":
                return new SecurityGroupResource(definition.Properties);
            case "instance":
                return new InstanceResource(definition.Properties);
            default:
                throw new NotSupportedException($"Resource type {definition.Type} is not supported");
        }
    }
}

// ICloudResource.cs
public interface ICloudResource
{
    string Id { get; }
    string Type { get; }
    Task DeployAsync();
    Task DeleteAsync();
}

// ICloudProvider.cs
public interface ICloudProvider
{
    Task DeployAsync(ICloudResource resource);
    Task DeleteAsync(ICloudResource resource);
}

// CloudProvider.cs (example implementation)
public class CloudProvider : ICloudProvider
{
    public async Task DeployAsync(ICloudResource resource)
    {
        // Simulate deployment with delay
        await Task.Delay(500); // Simulate network/cloud latency

        Console.WriteLine($"Deploying {resource.Type} {resource.Id} to cloud...");
    }

    public async Task DeleteAsync(ICloudResource resource)
    {
        // Simulate deletion
        await Task.Delay(300);
        Console.WriteLine($"Deleting {resource.Type} {resource.Id} from cloud...");
    }
}
